export class GatewayError extends Error {
  constructor(public code: string, public retryable: boolean) {
    super(code)
  }
}

export interface Gateway {
  refund(paymentId: string, amount: number, opts?: { idempotencyKey?: string }): Promise<void>
}

export const gateway: Gateway = createGateway(process.env.GATEWAY_URL)
